<script setup>
import { ref } from "vue"; import { useRouter } from "vue-router"; import { updateAdminProfile } from "../../services/adminRepository"; const router=useRouter(); let session=JSON.parse(localStorage.getItem('campus_session')||'null'); const form=ref({display_name:session?.name||'',college:'',major:'',grade:''}),saving=ref(false),toast=ref(''); async function save(){saving.value=true;try{const u=await updateAdminProfile(form.value);session={...session,name:u.display_name||u.username};localStorage.setItem('campus_session',JSON.stringify(session));toast.value='资料已保存'}catch(e){toast.value=e.response?.data?.detail||'保存失败'}finally{saving.value=false}}
</script>
<template><main class="portal-page admin-portal page-enter"><div class="portal-heading"><div><span class="portal-kicker">账户设置</span><h1>个人中心</h1><p>仅编辑后端真实支持的个人资料字段。</p></div></div><div v-if="toast" class="portal-toast">{{toast}}</div><section class="portal-panel profile-form"><h2>基本资料</h2><label>姓名<input v-model="form.display_name" required /></label><label>学院<input v-model="form.college" /></label><label>专业<input v-model="form.major" /></label><label>年级<input v-model="form.grade" /></label><div class="drawer-actions"><button class="primary-button" :disabled="saving" @click="save">{{saving?'保存中…':'保存资料'}}</button><button class="secondary-button" @click="router.push('/admin/dashboard')">返回概览</button></div></section></main></template>
